import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"30、【離】 離下離上","description":"橫渠易說 - 30、【離】 離下離上","frontmatter":{"title":"30、【離】 離下離上","description":"橫渠易說 - 30、【離】 離下離上"},"headers":[],"relativePath":"classics/hengqu/032.md","filePath":"classics/hengqu/032.md"}'),l={name:"classics/hengqu/032.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_30、【離】-離下離上" tabindex="-1">30、【離】 離下離上 <a class="header-anchor" href="#_30、【離】-離下離上" aria-label="Permalink to “30、【離】 離下離上”">​</a></h1><p>以柔麗乎中正，故利貞。</p><h3 id="彖曰-離-麗也-日月麗乎天-百穀草木麗乎土-重明以麗乎正-乃化成天下。柔麗乎中正故亨-是以畜牝牛吉也。" tabindex="-1">彖曰：離，麗也，日月麗乎天，百穀草木麗乎土，重明以麗乎正，乃化成天下。柔麗乎中正故亨，是以畜牝牛吉也。 <a class="header-anchor" href="#彖曰-離-麗也-日月麗乎天-百穀草木麗乎土-重明以麗乎正-乃化成天下。柔麗乎中正故亨-是以畜牝牛吉也。" aria-label="Permalink to “彖曰：離，麗也，日月麗乎天，百穀草木麗乎土，重明以麗乎正，乃化成天下。柔麗乎中正故亨，是以畜牝牛吉也。”">​</a></h3><p>日月草木麗天地，麗，附著也。</p><h3 id="象曰-明兩作-離-大人以繼明照於四方。" tabindex="-1">象曰：明兩作，離，大人以繼明照於四方。 <a class="header-anchor" href="#象曰-明兩作-離-大人以繼明照於四方。" aria-label="Permalink to “象曰：明兩作，離，大人以繼明照於四方。”">​</a></h3><p>明目達聽，繼明之道也。人患惰於博覽，惟大人能勉而繼之。</p><h3 id="初九-履錯然-敬之-無咎。-象曰-履錯之敬-以闢咎也。-履錯然-與之者多也。無應於上-無所朋附-以剛處下-物所願交-非矜慎之甚-何以免咎" tabindex="-1">初九，履錯然，敬之，無咎。 象曰：履錯之敬，以闢咎也。“履錯然”，與之者多也。無應於上，無所朋附，以剛處下，物所願交，非矜慎之甚，何以免咎! <a class="header-anchor" href="#初九-履錯然-敬之-無咎。-象曰-履錯之敬-以闢咎也。-履錯然-與之者多也。無應於上-無所朋附-以剛處下-物所願交-非矜慎之甚-何以免咎" aria-label="Permalink to “初九，履錯然，敬之，無咎。 象曰：履錯之敬，以闢咎也。“履錯然”，與之者多也。無應於上，無所朋附，以剛處下，物所願交，非矜慎之甚，何以免咎!”">​</a></h3><h3 id="六二-黃離-元吉。-象曰-黃離元吉-得中道也。" tabindex="-1">六二，黃離，元吉。 象曰：“黃離元吉”，得中道也。 <a class="header-anchor" href="#六二-黃離-元吉。-象曰-黃離元吉-得中道也。" aria-label="Permalink to “六二，黃離，元吉。 象曰：“黃離元吉”，得中道也。”">​</a></h3><h3 id="九三-日昃之離-不鼓缶而歌-則大耋之嗟-兇。-象曰-日昃之離-何可久也" tabindex="-1">九三，日昃之離，不鼓缶而歌，則大耋之嗟，兇。 象曰：日昃之離，何可久也! <a class="header-anchor" href="#九三-日昃之離-不鼓缶而歌-則大耋之嗟-兇。-象曰-日昃之離-何可久也" aria-label="Permalink to “九三，日昃之離，不鼓缶而歌，則大耋之嗟，兇。 象曰：日昃之離，何可久也!”">​</a></h3><p>明正將老，離過於中，故哀樂之不常其德，凡人不能久也。故君子為德，夭壽不貳。 人向衰暮則尤樂聽聲音，蓋留連光景，視桑榆之暮景不足，則貪於為樂，惟鄭衛之音能令人生此意。易謂“不鼓缶而歌則大耋之嗟兇”，悲衰暮故為樂，不為則復嗟年景之不足也。</p><h3 id="九四-突如其來如-焚如-死如-棄如。-象曰-突如其來如-無所容也。" tabindex="-1">九四，突如其來如，焚如，死如，棄如。 象曰：“突如其來如”，無所容也。 <a class="header-anchor" href="#九四-突如其來如-焚如-死如-棄如。-象曰-突如其來如-無所容也。" aria-label="Permalink to “九四，突如其來如，焚如，死如，棄如。 象曰：“突如其來如”，無所容也。”">​</a></h3><p>處多懼之地而以乘剛，故其來也遽，其處也危，無所容安，如見棄逐，皆所麗之失中也。三剛而 不可乘，五正而不見容。</p><h3 id="六五-出涕沱若-戚嗟若-吉。-象曰-六五之吉-離王公也。" tabindex="-1">六五，出涕沱若，戚嗟若，吉。 象曰：六五之吉，離王公也。 <a class="header-anchor" href="#六五-出涕沱若-戚嗟若-吉。-象曰-六五之吉-離王公也。" aria-label="Permalink to “六五，出涕沱若，戚嗟若，吉。 象曰：六五之吉，離王公也。”">​</a></h3><p>言王公之貴，人之所附，下以剛進，己雖憂危，終以得眾而吉者，柔麗中正也。</p><h3 id="上九-王用出徵-有嘉折首-獲匪其醜-無咎。-象曰-王用出徵-以正邦也。-有嘉折首-服而善之也。-獲匪其醜-執訊弗賓-示威以正邦而已-離道已成-然後不附可徵。" tabindex="-1">上九，王用出徵，有嘉折首，獲匪其醜，無咎。 象曰：“王用出徵”，以正邦也。“有嘉折首”，服而善之也。“獲匪其醜”，執訊弗賓，示威以正邦而已，離道已成，然後不附可徵。 <a class="header-anchor" href="#上九-王用出徵-有嘉折首-獲匪其醜-無咎。-象曰-王用出徵-以正邦也。-有嘉折首-服而善之也。-獲匪其醜-執訊弗賓-示威以正邦而已-離道已成-然後不附可徵。" aria-label="Permalink to “上九，王用出徵，有嘉折首，獲匪其醜，無咎。 象曰：“王用出徵”，以正邦也。“有嘉折首”，服而善之也。“獲匪其醜”，執訊弗賓，示威以正邦而已，離道已成，然後不附可徵。”">​</a></h3>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
